using System; using System.Web.Services; using BabcoUnloadCompare.Web.Models; using BabcoUnloadCompare.Web.Services;
namespace BabcoUnloadCompare.Web { public partial class UnloadCompareDetails:System.Web.UI.Page { protected void Page_Load(object s,EventArgs e){} [WebMethod] public static ApiResult<object> GetDetails(int receivingId){try{return new ApiResult<object>{IsSuccess=true,Data=new DataAccess().GetDetails(receivingId)};}catch(Exception ex){return new ApiResult<object>{IsSuccess=false,Message=ex.Message};}} [WebMethod] public static ApiResult<object> Verify(int receivingId,string notes){try{new DataAccess().Verify(receivingId,notes);return new ApiResult<object>{IsSuccess=true,Message="Receiving record verified."};}catch(Exception ex){return new ApiResult<object>{IsSuccess=false,Message=ex.Message};}} [WebMethod] public static ApiResult<object> Complete(int receivingId,string notes){try{new DataAccess().SetStatus(receivingId,"Completed",notes);return new ApiResult<object>{IsSuccess=true,Message="Receiving record completed."};}catch(Exception ex){return new ApiResult<object>{IsSuccess=false,Message=ex.Message};}} } }
